$ErrorActionPreference='Stop';. "$PSScriptRoot/activate-environment.ps1";Import-Module "$PSScriptRoot/BusinessOS.Engineering.psm1" -Force
$Root=Get-BusinessOSRepoRoot;$started=[DateTimeOffset]::UtcNow.ToString('o');$stage='initialization';$last='none';$exitCode=0;$failure='none';$formatStatus='NOT_RUN';$buildStatus='NOT_RUN';$art="$Root/artifacts/test-results";$smoke="$Root/artifacts/smoke-test";foreach($p in $art,$smoke){if(Test-Path $p){Remove-Item $p -Recurse -Force};New-Item -ItemType Directory -Force $p|Out-Null}
function Run([string]$Name,[scriptblock]$Action){$script:stage=$Name;&$Action;$script:last=$Name}
try{if(-not$IsWindows){throw 'verify-windows.ps1 must run on Windows.'};Run doctor {Invoke-CheckedCommand pwsh @('-NoProfile','-File',"$PSScriptRoot/doctor.ps1",'-Mode','Windows','-SkipEnvironmentTests') $Root};Run restore {Invoke-CheckedCommand dotnet @('tool','restore') $Root;Invoke-CheckedCommand dotnet @('restore','BusinessOS.sln') $Root};Run format {Invoke-CheckedCommand dotnet @('format','BusinessOS.sln','--verify-no-changes') $Root;$script:formatStatus='PASS'};Run build {Invoke-CheckedCommand dotnet @('build','BusinessOS.sln','-c','Release','--no-restore') $Root;Invoke-CheckedCommand dotnet @('build','tests/BusinessOS.RecoverySmokeFixture/BusinessOS.RecoverySmokeFixture.csproj','-c','Release') $Root;$script:buildStatus='PASS'};Run tests {Invoke-CheckedCommand dotnet @('test','BusinessOS.sln','-c','Release','--no-build','--logger','trx','--results-directory',$art) $Root};Run trx-verification {Invoke-CheckedCommand pwsh @('-NoProfile','-File',"$PSScriptRoot/verify-test-results.ps1",'-ResultsDirectory',$art) $Root;Invoke-CheckedCommand pwsh @('-NoProfile','-File',"$PSScriptRoot/test-verify-test-results.ps1") $Root};Run environment-tests {& pwsh -NoProfile -File "$Root/tests/environment/Environment.Tests.ps1" 2>&1|Tee-Object "$Root/.cache/environment-tests.log";if($LASTEXITCODE){throw 'Environment tests failed'}};Run vulnerability-scan {Invoke-CheckedCommand pwsh @('-NoProfile','-File',"$PSScriptRoot/check-vulnerable-packages.ps1",'-ProjectOrSolution','BusinessOS.sln') $Root};Run migration-check {$migrationRoot='src/Modules/Companies/BusinessOS.Modules.Companies.Infrastructure/Persistence/Migrations';$snapshot=Get-ChildItem $migrationRoot -Filter '*ModelSnapshot.cs'|Select-Object -First 1;$beforeFiles=@(Get-ChildItem $migrationRoot -File|ForEach-Object Name);$beforeStatus=@(&git status --porcelain -- $migrationRoot);$beforeHash=if($snapshot){(Get-FileHash $snapshot.FullName -Algorithm SHA256).Hash}else{$null};$o=&dotnet ef migrations has-pending-model-changes --project src/Modules/Companies/BusinessOS.Modules.Companies.Infrastructure/BusinessOS.Modules.Companies.Infrastructure.csproj --startup-project src/Modules/Companies/BusinessOS.Modules.Companies.Infrastructure/BusinessOS.Modules.Companies.Infrastructure.csproj --context CompaniesDbContext 2>&1;if($LASTEXITCODE-or($o-join"`n")-notmatch'No changes have been made'){throw($o-join"`n")};$afterFiles=@(Get-ChildItem $migrationRoot -File|ForEach-Object Name);$afterStatus=@(&git status --porcelain -- $migrationRoot);$afterHash=if($snapshot){(Get-FileHash $snapshot.FullName -Algorithm SHA256).Hash}else{$null};[ordered]@{status='PASS';pendingModelChanges=$false;newMigrationCreated=@($afterFiles|Where-Object{$beforeFiles-notcontains$_}).Count-gt 0;snapshotModified=($beforeHash-ne$afterHash-or($afterStatus-join'|')-ne($beforeStatus-join'|'));snapshotSha256Before=$beforeHash;snapshotSha256After=$afterHash;migrationFilesBefore=$beforeFiles;migrationFilesAfter=$afterFiles}|ConvertTo-Json -Depth 5|Set-Content "$Root/.cache/migration-evidence.json"};foreach($scenario in 'Ready','PersistenceFailure','PersistenceFailureThenReady','RecoveryFromReady','RecoveryFromStartupFailure'){Run "smoke-$scenario" {Invoke-CheckedCommand pwsh @('-NoProfile','-File',"$PSScriptRoot/smoke-test-desktop.ps1",'-Configuration','Release','-Scenario',$scenario) $Root;$file="$smoke/scenarios/$scenario.json";if(-not(Test-Path $file)){throw "Missing scenario evidence: $file"}}};Run final-doctor {Invoke-CheckedCommand pwsh @('-NoProfile','-File',"$PSScriptRoot/doctor.ps1",'-Mode','Windows','-SkipEnvironmentTests') $Root};$stage='complete';$last='complete'}catch{$exitCode=if($LASTEXITCODE){$LASTEXITCODE}else{1};$failure=$_.Exception.Message;if($stage-eq'format'){$formatStatus='FAIL'};if($stage-eq'build'){$buildStatus='FAIL'};Write-Host "Gate failure: $($_.Exception.Message)"}finally{try{& "$PSScriptRoot/write-ci-summary.ps1" -Gate windows -Status $(if($exitCode){'FAIL'}else{'PASS'}) -FailureStage $(if($exitCode){$stage}else{'none'}) -FailureMessage $(if($exitCode){$failure}else{'none'}) -LastCompletedStage $last -StartedAtUtc $started -FormatStatus $formatStatus -BuildStatus $buildStatus}catch{Write-Host "Summary generation failed: $_";if(-not$exitCode){$exitCode=1}}};if($exitCode){exit $exitCode}
